CREATE TABLE IF NOT EXISTS node_identity(id INTEGER PRIMARY KEY CHECK(id=1),cluster TEXT NOT NULL,private_key BLOB NOT NULL,public_key BLOB NOT NULL,signing_key BLOB NOT NULL,age_key TEXT NOT NULL,sequence INTEGER NOT NULL DEFAULT 0,config TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS account(id INTEGER PRIMARY KEY CHECK(id=1),username TEXT NOT NULL,password_hash TEXT NOT NULL,entrance TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,secret TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS account_navigation(account_id INTEGER PRIMARY KEY CHECK(account_id=1) REFERENCES account(id),revision INTEGER NOT NULL,order_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,token_hash BLOB UNIQUE NOT NULL,csrf_token TEXT NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,last_seen_at INTEGER NOT NULL,remote_address TEXT NOT NULL,revoked_at INTEGER);
CREATE TABLE IF NOT EXISTS members(id TEXT PRIMARY KEY,body TEXT NOT NULL,version INTEGER NOT NULL,issuer TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admissions(id TEXT PRIMARY KEY,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS revocations(id TEXT PRIMARY KEY,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS enrollment_tokens(id TEXT PRIMARY KEY,token_hash BLOB UNIQUE NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,consumed_at INTEGER,revoked_at INTEGER,member_id TEXT);
CREATE TABLE IF NOT EXISTS queue(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,origin TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,request_key TEXT NOT NULL,request_digest BLOB NOT NULL,phase TEXT NOT NULL DEFAULT 'queued',body TEXT NOT NULL,terminal INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS queue_key ON queue(origin,request_key) WHERE request_key<>'';
CREATE TABLE IF NOT EXISTS plans(id TEXT PRIMARY KEY,body TEXT NOT NULL,operation_id TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY,kind TEXT NOT NULL,object TEXT NOT NULL,sequence INTEGER NOT NULL,body TEXT NOT NULL,database_name TEXT NOT NULL,uploaded INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS pending_records ON records(uploaded,sequence);
CREATE INDEX IF NOT EXISTS object_records ON records(kind,object,sequence DESC);
CREATE TABLE IF NOT EXISTS storage_credentials(id TEXT PRIMARY KEY,secret TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS observed_versions(id TEXT PRIMARY KEY,sequence INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS monitoring_samples(collected_at INTEGER PRIMARY KEY,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS firewall_config(id INTEGER PRIMARY KEY CHECK(id=1),body TEXT NOT NULL,confirmed TEXT NOT NULL DEFAULT 'null');
CREATE TABLE IF NOT EXISTS public_addresses(owner TEXT PRIMARY KEY,revision INTEGER NOT NULL,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS peer_trust_policy(id INTEGER PRIMARY KEY CHECK(id=1),body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS peer_trust_status(id INTEGER PRIMARY KEY CHECK(id=1),body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS peer_trust_target(id INTEGER PRIMARY KEY CHECK(id=1),body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS api_tokens(id TEXT PRIMARY KEY,token_hash BLOB UNIQUE NOT NULL,body TEXT NOT NULL,created_at INTEGER NOT NULL,revision INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS managed_database_clusters(id TEXT PRIMARY KEY,body TEXT NOT NULL,revision INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS managed_database_instances(id TEXT PRIMARY KEY,body TEXT NOT NULL,connection TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS database_workflows(id TEXT PRIMARY KEY,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS managed_database_versions(id TEXT NOT NULL,revision INTEGER NOT NULL,connection TEXT NOT NULL,PRIMARY KEY(id,revision));
